#!/bin/zsh
# type a string into the guest via qemu monitor sendkey
s="$1"
sock=/tmp/qemu-mon.sock
send(){ printf 'sendkey %s\n' "$1" | /opt/homebrew/bin/socat - UNIX-CONNECT:$sock >/dev/null 2>&1; }
for (( i=0; i<${#s}; i++ )); do
  c="${s:$i:1}"
  case "$c" in
    [a-z]) send "$c" ;;
    [A-Z]) send "shift-$(echo $c|tr A-Z a-z)" ;;
    [0-9]) send "$c" ;;
    " ") send spc ;;
    "\\") send 0x2b ;;
    ":") send shift-0x27 ;;
    ".") send 0x34 ;;
    "-") send 0x0c ;;
    "{") send shift-0x1a ;;
    "}") send shift-0x1b ;;
    '"') send shift-0x28 ;;
    *) ;;
  esac
done
